using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Input;
using ProjectTower.gamestate;
using ProjectTower.player;
using ProjectTower.player.dialog.levels;

namespace ProjectTower.config;

public class InputProfile
{
	public const int KEY_LEFT = 0;

	public const int KEY_RIGHT = 1;

	public const int KEY_UP = 2;

	public const int KEY_DOWN = 3;

	public const int KEY_ATTACK = 4;

	public const int KEY_STRONG = 5;

	public const int KEY_JUMP = 6;

	public const int KEY_USE = 7;

	public const int KEY_DODGE = 8;

	public const int KEY_OFFHAND = 9;

	public const int KEY_SWITCH_LOADOUT = 10;

	public const int KEY_INVENTORY = 11;

	public const int KEY_USE_ITEM = 12;

	public const int KEY_ITEM_LEFT = 13;

	public const int KEY_ITEM_RIGHT = 14;

	public const int KEY_TORCH = 15;

	public const int KEY_LOOK_LEFT = 16;

	public const int KEY_LOOK_RIGHT = 17;

	public const int KEY_LOOK_UP = 18;

	public const int KEY_LOOK_DOWN = 19;

	public const int KEY_ACCEPT = 20;

	public const int KEY_CANCEL = 21;

	public const int KEY_Y_OPTION = 22;

	public const int KEY_X_OPTION = 23;

	public const int TOTAL_KEYS = 24;

	public InputMapping[] inputMapping;

	public bool mouseEnable;

	public bool showMouse;

	public bool keysEnable;

	public bool keyMouseEnable;

	public Vector2 mouseVec;

	public ButtonState msLeftButton;

	public ButtonState msRightButton;

	public ButtonState msMiddleButton;

	public ButtonState msXButton1;

	public ButtonState msXButton2;

	private KeyboardState pks;

	private GamePadState pgs;

	private int ID;

	private static int GetKeyFromScancode(Keys key)
	{
		return (int)key;
	}

	public void Reset()
	{
		int iD = ID;
		inputMapping = new InputMapping[24];
		inputMapping[0] = new InputMapping(iD, "left", GetKeyFromScancode(Keys.A), -6, 0);
		inputMapping[1] = new InputMapping(iD, "right", GetKeyFromScancode(Keys.D), -7, 0);
		inputMapping[2] = new InputMapping(iD, "up", GetKeyFromScancode(Keys.W), -8, 0);
		inputMapping[3] = new InputMapping(iD, "down", GetKeyFromScancode(Keys.S), -9, 0);
		inputMapping[4] = new InputMapping(iD, "attack", -2, -16, 0);
		inputMapping[5] = new InputMapping(iD, "strong", -1, -17, 0);
		inputMapping[7] = new InputMapping(iD, "use", GetKeyFromScancode(Keys.C), -15, 0);
		inputMapping[6] = new InputMapping(iD, "jump", GetKeyFromScancode(Keys.Space), -14, 0);
		inputMapping[8] = new InputMapping(iD, "dodge", GetKeyFromScancode(Keys.LeftShift), -19, 0);
		inputMapping[9] = new InputMapping(iD, "offhand", GetKeyFromScancode(Keys.LeftControl), -21, 0);
		inputMapping[10] = new InputMapping(iD, "switch_loadout", GetKeyFromScancode(Keys.Tab), -20, 0);
		inputMapping[11] = new InputMapping(iD, "inventory", GetKeyFromScancode(Keys.Escape), -22, 0);
		inputMapping[12] = new InputMapping(iD, "use_item", GetKeyFromScancode(Keys.F), -18, 0);
		inputMapping[13] = new InputMapping(iD, "item_left", GetKeyFromScancode(Keys.Q), -10, 0);
		inputMapping[14] = new InputMapping(iD, "item_right", GetKeyFromScancode(Keys.E), -11, 0);
		inputMapping[15] = new InputMapping(iD, "torch", GetKeyFromScancode(Keys.R), -13, 0);
		inputMapping[16] = new InputMapping(iD, "look_left", GetKeyFromScancode(Keys.Left), -24, 0);
		inputMapping[17] = new InputMapping(iD, "look_right", GetKeyFromScancode(Keys.Right), -25, 0);
		inputMapping[18] = new InputMapping(iD, "look_up", GetKeyFromScancode(Keys.Up), -26, 0);
		inputMapping[19] = new InputMapping(iD, "look_down", GetKeyFromScancode(Keys.Down), -27, 0);
		inputMapping[20] = new InputMapping(iD, "accept", GetKeyFromScancode(Keys.Space), -14, -2);
		inputMapping[21] = new InputMapping(iD, "cancel", GetKeyFromScancode(Keys.Escape), -15, 0);
		inputMapping[22] = new InputMapping(iD, "y_option", GetKeyFromScancode(Keys.Tab), -17, -1);
		inputMapping[23] = new InputMapping(iD, "x_option", GetKeyFromScancode(Keys.Back), -16, GetKeyFromScancode(Keys.Back));
	}

	public InputProfile(int idx)
	{
		ID = idx;
		Reset();
		mouseEnable = true;
	}

	public void Update(int gamepadIdx)
	{
		KeyboardState keyboardState = GlobalInputMgr.GetKeyboardState();
		GamePadState gamePadState = ((gamepadIdx > -1) ? GamePad.GetState((PlayerIndex)gamepadIdx, GamePadDeadZone.None) : default(GamePadState));
		for (int i = 0; i < 24; i++)
		{
			inputMapping[i].prevPressed = inputMapping[i].pressed;
			inputMapping[i].pressed = false;
			inputMapping[i].pressedVal = 0f;
		}
		for (int j = 0; j < 2; j++)
		{
			if (ID == 0)
			{
				Keys[] pressedKeys = keyboardState.GetPressedKeys();
				foreach (Keys keys in pressedKeys)
				{
					for (int l = 0; l < 24; l++)
					{
						if (inputMapping[l].keys[j] == (int)keys)
						{
							inputMapping[l].pressed = true;
							inputMapping[l].pressedVal = 1f;
							keysEnable = true;
							keyMouseEnable = true;
						}
					}
				}
			}
			if (gamepadIdx > -1)
			{
				_ = ID;
				_ = 1;
				if (!GameStateManager.IsGamepadUsedByCoopPlayer(ID, gamepadIdx))
				{
					for (int m = 0; m < 24; m++)
					{
						bool flag = false;
						float num = -1f;
						switch (inputMapping[m].keys[j])
						{
						case -14:
							if (gamePadState.Buttons.A == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -15:
							if (gamePadState.Buttons.B == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -16:
							if (gamePadState.Buttons.X == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -17:
							if (gamePadState.Buttons.Y == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -28:
							if (gamePadState.Buttons.LeftStick == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -29:
							if (gamePadState.Buttons.RightStick == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -23:
							if (gamePadState.Buttons.Back == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -22:
							if (gamePadState.Buttons.Start == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -20:
							if (gamePadState.Buttons.LeftShoulder == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -18:
							if (gamePadState.Buttons.RightShoulder == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -6:
							if (gamePadState.ThumbSticks.Left.X < -0.3f)
							{
								flag = true;
							}
							num = 0f - gamePadState.ThumbSticks.Left.X;
							break;
						case -7:
							if (gamePadState.ThumbSticks.Left.X > 0.3f)
							{
								flag = true;
							}
							num = gamePadState.ThumbSticks.Left.X;
							break;
						case -9:
							if (gamePadState.ThumbSticks.Left.Y < -0.3f)
							{
								flag = true;
							}
							num = 0f - gamePadState.ThumbSticks.Left.Y;
							break;
						case -8:
							if (gamePadState.ThumbSticks.Left.Y > 0.3f)
							{
								flag = true;
							}
							num = gamePadState.ThumbSticks.Left.Y;
							break;
						case -24:
							if (gamePadState.ThumbSticks.Right.X < -0.3f)
							{
								flag = true;
							}
							num = 0f - gamePadState.ThumbSticks.Right.X;
							break;
						case -25:
							if (gamePadState.ThumbSticks.Right.X > 0.3f)
							{
								flag = true;
							}
							num = gamePadState.ThumbSticks.Right.X;
							break;
						case -27:
							if (gamePadState.ThumbSticks.Right.Y < -0.3f)
							{
								flag = true;
							}
							num = 0f - gamePadState.ThumbSticks.Right.Y;
							break;
						case -26:
							if (gamePadState.ThumbSticks.Right.Y > 0.3f)
							{
								flag = true;
							}
							num = gamePadState.ThumbSticks.Right.Y;
							break;
						case -21:
							if (gamePadState.Triggers.Left > 0.3f)
							{
								flag = true;
							}
							num = gamePadState.Triggers.Left;
							break;
						case -19:
							if (gamePadState.Triggers.Right > 0.3f)
							{
								flag = true;
							}
							num = gamePadState.Triggers.Right;
							break;
						case -10:
							if (gamePadState.DPad.Left == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -11:
							if (gamePadState.DPad.Right == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -12:
							if (gamePadState.DPad.Up == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						case -13:
							if (gamePadState.DPad.Down == ButtonState.Pressed)
							{
								flag = true;
							}
							break;
						}
						if (flag)
						{
							inputMapping[m].pressed = true;
							if (num < 0f)
							{
								inputMapping[m].pressedVal = 1f;
							}
							else
							{
								inputMapping[m].pressedVal = Math.Max(inputMapping[m].pressedVal, num);
							}
							keyMouseEnable = false;
						}
						else
						{
							inputMapping[m].pressedVal = Math.Max(inputMapping[m].pressedVal, num);
							if (inputMapping[m].pressedVal < 0f)
							{
								inputMapping[m].pressedVal = 0f;
							}
						}
					}
				}
			}
			if (!GameStateManager.activeFocus || ID != 0)
			{
				continue;
			}
			if (msLeftButton == ButtonState.Pressed)
			{
				keyMouseEnable = true;
				for (int n = 0; n < 24; n++)
				{
					if (inputMapping[n].keys[j] == -2)
					{
						inputMapping[n].pressed = true;
					}
				}
			}
			if (msRightButton == ButtonState.Pressed)
			{
				keyMouseEnable = true;
				for (int num2 = 0; num2 < 24; num2++)
				{
					if (inputMapping[num2].keys[j] == -1)
					{
						inputMapping[num2].pressed = true;
					}
				}
			}
			if (msMiddleButton == ButtonState.Pressed)
			{
				keyMouseEnable = true;
				for (int num3 = 0; num3 < 24; num3++)
				{
					if (inputMapping[num3].keys[j] == -3)
					{
						inputMapping[num3].pressed = true;
					}
				}
			}
			if (msXButton1 == ButtonState.Pressed)
			{
				keyMouseEnable = true;
				for (int num4 = 0; num4 < 24; num4++)
				{
					if (inputMapping[num4].keys[j] == -4)
					{
						inputMapping[num4].pressed = true;
					}
				}
			}
			if (msXButton2 != ButtonState.Pressed)
			{
				continue;
			}
			keyMouseEnable = true;
			for (int num5 = 0; num5 < 24; num5++)
			{
				if (inputMapping[num5].keys[j] == -5)
				{
					inputMapping[num5].pressed = true;
				}
			}
		}
		pks = keyboardState;
		pgs = gamePadState;
	}

	internal void WriteConfig(List<string> config)
	{
		for (int i = 0; i < 24; i++)
		{
			config.Add(inputMapping[i].configName + "=" + inputMapping[i].keys[0] + "|" + inputMapping[i].keys[1] + "|" + inputMapping[i].keys[2]);
		}
	}

	internal void ReadConfig(string name, string val)
	{
		for (int i = 0; i < 24; i++)
		{
			if (!(inputMapping[i].configName == name) || !val.Contains('|'))
			{
				continue;
			}
			try
			{
				string[] array = val.Split('|');
				if (array.Length == 2)
				{
					int num = Convert.ToInt32(array[0]);
					int num2 = Convert.ToInt32(array[1]);
					inputMapping[i].SetKey(num, InputMapping.IntKeyToName(num), num2, InputMapping.IntKeyToName(num2), 0, InputMapping.IntKeyToName(0));
				}
				else if (array.Length == 3)
				{
					int num3 = Convert.ToInt32(array[0]);
					int num4 = Convert.ToInt32(array[1]);
					int num5 = Convert.ToInt32(array[2]);
					inputMapping[i].SetKey(num3, InputMapping.IntKeyToName(num3), num4, InputMapping.IntKeyToName(num4), num5, InputMapping.IntKeyToName(num5));
				}
				else
				{
					inputMapping[i].SetKey(0, InputMapping.IntKeyToName(0), 0, InputMapping.IntKeyToName(0), 0, InputMapping.IntKeyToName(0));
				}
			}
			catch (Exception)
			{
				inputMapping[i].SetKey(0, InputMapping.IntKeyToName(0), 0, InputMapping.IntKeyToName(0), 0, InputMapping.IntKeyToName(0));
			}
		}
	}

	internal bool IsMouseKeyActive()
	{
		if (keyMouseEnable && ID == 0)
		{
			return true;
		}
		return false;
	}

	internal StringBuilder GetKeyName(int inputIdx)
	{
		if (keyMouseEnable && ID == 0)
		{
			if (mouseEnable && PlayerMgr.GetMainPlayer() != null && (PlayerMgr.GetMainPlayer().dialog.menuMgr.curLev != 8 || ((Upgrades)PlayerMgr.GetMainPlayer().dialog.menuMgr.menuLevel[8]).page != 3) && inputMapping[inputIdx].keys[2] > -6 && inputMapping[inputIdx].keys[2] < 0)
			{
				return inputMapping[inputIdx].keyName[2];
			}
			if (inputMapping[inputIdx].keys[0] > -6)
			{
				return inputMapping[inputIdx].keyName[0];
			}
			if (inputMapping[inputIdx].keys[1] > -6)
			{
				return inputMapping[inputIdx].keyName[1];
			}
		}
		else
		{
			if (inputMapping[inputIdx].keys[0] <= -6)
			{
				return inputMapping[inputIdx].keyName[0];
			}
			if (inputMapping[inputIdx].keys[1] <= -6)
			{
				return inputMapping[inputIdx].keyName[1];
			}
		}
		return inputMapping[inputIdx].keyName[0];
	}

	internal int CheckConflict(int keyEnter, int keyIdx, int mapIdx)
	{
		for (int i = 0; i < 20; i++)
		{
			for (int j = 0; j < 2; j++)
			{
				if ((i != keyIdx || j != mapIdx) && inputMapping[i].keys[j] == keyEnter)
				{
					return i;
				}
			}
		}
		return -1;
	}
}
