	{
		return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Personal), "Salt and Sanctuary/config");
	}

	public static void MigrateConfig()
	{
		if (Environment.OSVersion.Platform != PlatformID.Win32NT || Directory.Exists(GetNewDirectory()) || !Directory.Exists(GetOldDirectory()) || new DirectoryInfo(GetOldDirectory()).GetFiles("*.ini").Length < 1 || Directory.Exists(GetNewDirectory()))
		{
			return;
		}
		Directory.CreateDirectory(GetNewDirectory());
		if (Directory.Exists(GetOldDirectory()))
		{
			FileInfo[] files = new DirectoryInfo(GetOldDirectory()).GetFiles("*.ini");
			foreach (FileInfo fileInfo in files)
