				character = CharMgr.GetPlayerCharacter(coopPlayer);
			}
		}
		if (mainCharacter != null)
		{
			int sanctuaryIn = MapMgr.sanctuaryMgr.GetSanctuaryIn((mainCharacter.hp <= 0f && GameStateManager.coopPlayerIdx > -1) ? character : mainCharacter);
			if (sanctuaryIn > -1 && MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].creed != 0 && !MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].shrine && !(MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].desecrationFrame > 0f))
			{
				num = 1;
			}
			int layer = CharCols.GetLayer(mainCharacter.loc + new Vector2(0f, -16f));
			if ((uint)(layer - 21) <= 2u)
			{
				num = 10;
			}
			int cannedArenaIdx = MapMgr.map.triggerMgr.GetCannedArenaIdx((mainCharacter.hp <= 0f && GameStateManager.coopPlayerIdx > -1) ? character : mainCharacter);
			if (cannedArenaIdx > -1 && MapMgr.map.triggerMgr.GetAnyArenaBossIdx(cannedArenaIdx) && BossToast.confirmedOkay)
			{
				num = 0;
				int arenaBossIdx = MapMgr.map.triggerMgr.GetArenaBossIdx(cannedArenaIdx, 0);
				if (arenaBossIdx > -1)
				{
					switch (MonsterCatalog.catalog[CharMgr.character[arenaBossIdx].monsterIdx].defIdx)
					{
					case 3:
					case 20:
					case 29:
					case 34:
					case 54:
					case 62:
					case 75:
					case 76:
					case 97:
						num = 6;
						break;
					case 92:
						num = 9;
						break;
					default:
						num = 0;
						break;
					}
				}
			}
			if (GameStateManager.wordsFrame > 0f && GameStateManager.wordsMode == 1)
			{
				num = -1;
			}
		}
		for (int i = 0; i < PlayerMgr.player.Length; i++)
		{
			if (PlayerMgr.player[i].active && PlayerMgr.player[i].camMgr.scarecrowfreak > 0.5f)
			{
				num = 5;
			}
		}
		ambientFrame += frameTime;
		if (num == -1 && goalTrack > -1 && library[goalTrack].mood)
		{
			num = goalTrack;
		}
		if (ambientFrame > 60f)
		{
			int num2 = 0;
			if (mainCharacter != null)
			{
				num2 = CharCols.GetLayer(mainCharacter.loc + new Vector2(0f, -16f));
			}
			if (num == -1 && GameStateManager.gameState == 1)
			{
				bool flag = true;
				if ((uint)(num2 - 6) <= 1u)
				{
					flag = false;
				}
				if (flag)
				{
					switch (Rand.GetRandomInt(0, 3))
					{
					case 0:
						num = 2;
						break;
					case 1:
						num = 3;
						break;
					case 2:
						num = 4;
						break;
					}
				}
			}
			ambientFrame = Rand.GetRandomFloat(-240f, -200f);
		}
		if (DebugMgr.vidMode != 0)
		{
			num = -1;
		}
		switch (GameStateManager.gameState)
		{
		case 4:
			num = 8;
			GameStateManager.endGameMusicFrame = 0f;
			break;
		default:
			num = -1;
			GameStateManager.endGameMusicFrame = 0f;
			break;
		case 1:
			break;
		}
		if (GameStateManager.endGameMusicFrame > 0f)
		{
			num = 7;
			GameStateManager.endGameMusicFrame += realTime;
			EndGameMgr.UpdateWisps();
		}
		SetMusic(num);
		float num3 = 1f;
		if (goalTrack != currentTrack)
		{
			switch (mediaState)
			{
			case MediaState.Playing:
				vol -= frameTime * num3;
				if (vol <= 0f || (goalTrack > -1 && library[goalTrack].alwaysStart))
				{
					if (goalTrack > -1 && library[goalTrack].alwaysStart)
					{
						vol = 1f;
					}
					MediaPlayer.Stop();
					currentTrack = goalTrack;
					if (currentTrack > -1)
					{
						musicSnd.PlayCue(library[currentTrack].name);
						musicVol = musicSnd.GetVol(library[currentTrack].name);
						SetMusicVolume(vol * musicVol);
					}
				}
				else
				{
					SetMusicVolume(vol * musicVol);
				}
				break;
			case MediaState.Stopped:
				currentTrack = goalTrack;
				if (currentTrack > -1)
				{
					musicSnd.PlayCue(library[currentTrack].name);
					musicVol = musicSnd.GetVol(library[currentTrack].name);
					SetMusicVolume(vol * musicVol);
				}
				break;
			}
			return;
		}
		if (mediaState != MediaState.Playing)
		{
			currentTrack = (goalTrack = -1);
		}
		if (vol < 1f)
		{
			vol += frameTime * num3;
			if (vol > 1f)
			{
				vol = 1f;
			}
		}
		SetMusicVolume(vol * musicVol);
	}
}
