		internal void Update()
		{
			Vector2 vector = loc;
			if (GameStateManager.coopPlayerIdx > -1)
			{
				vector.X = (PlayerMgr.GetMainPlayer().camMgr.scroll.X + PlayerMgr.GetCoopPlayer().camMgr.scroll.X) / 2f;
			}
			else
			{
				vector.X = ScrollManager.scroll.X;
			}
			float num = (loc.X - vector.X) / 1280f;
			if (num > 1f)
			{
				num = 1f;
			}
			if (num < -1f)
			{
				num = -1f;
			}
			if (num >= -1f && num <= 1f)
			{
				cue.Pan = num;
			}
		}

		internal void Set(SoundEffectInstance cue, Vector2 loc)
		{
			if (this.cue != null)
			{
				this.cue.Dispose();
			}
			this.cue = cue;
			this.loc = loc;
		}
	}

