namespace AudioEdit.sfx;

public class BankSound
{
	public string name;

	public List<string> wavBank;

	public List<string> wav;

	public int[] wavBankIdx;

	public int[] wavIdx;

	public float volume;

	public float pitch;

	public int category;

	private bool idxSet;

	public BankSound()
	{
		name = "";
		wav = new List<string>();
		wavBank = new List<string>();
		volume = 1f;
		pitch = 0f;
	}

	public void SetIdx(SoundManager sndMgr)
	{
		wavBankIdx = new int[wavBank.Count];
		wavIdx = new int[wav.Count];
		idxSet = true;
		for (int i = 0; i < wavBankIdx.Length; i++)
		{
			wavBankIdx[i] = -1;
			wavIdx[i] = -1;
			for (int j = 0; j < sndMgr.waveBank.Length; j++)
			{
				if (sndMgr.waveBank[j].title == wavBank[i])
				{
					wavBankIdx[i] = j;
					break;
				}
			}
			if (wavBankIdx[i] == -1)
			{
				idxSet = false;
				break;
			}
			MgrWaveBank mgrWaveBank = sndMgr.waveBank[wavBankIdx[i]];
			for (int k = 0; k < mgrWaveBank.bankWave.Length; k++)
			{
				if (mgrWaveBank.bankWave[k].name == wav[i])
				{
					wavIdx[i] = k;
					break;
				}
			}
			if (wavIdx[i] == -1)
			{
				idxSet = false;
				break;
			}
		}
	}

	public void Play(SoundManager sndMgr)
	{
		Play(sndMgr, 1f, 0f);
	}

	public void Play(SoundManager sndMgr, float playVolume, float playPan)
	{
		if (!idxSet)
		{
			SetIdx(sndMgr);
		}
		if (wavIdx == null || wavBankIdx == null)
		{
			return;
		}
		for (int i = 0; i < wavIdx.Length; i++)
		{
			if (wavBankIdx[i] > -1 && wavIdx[i] > -1)
			{
				playVolume *= (float)ConfigMgr.sfx / 10f;
				sndMgr.waveBank[wavBankIdx[i]].bankWave[wavIdx[i]].Play(volume * playVolume, pitch, playPan);
			}
		}
	}

	public SoundEffectInstance GetInstance(SoundManager sndMgr)
	{
		if (!idxSet)
		{
			SetIdx(sndMgr);
		}
		if (wavIdx != null && wavBankIdx != null)
		{
			for (int i = 0; i < wavIdx.Length; i++)
			{
				if (wavBankIdx[i] > -1 && wavIdx[i] > -1)
				{
					SoundEffectInstance instance = sndMgr.waveBank[wavBankIdx[i]].bankWave[wavIdx[i]].GetInstance();
					if (instance == null)
					{
						return null;
					}
					instance.Volume = volume;
					return instance;
				}
			}
		}
		return null;
	}

	public void Read(BinaryReader reader)
	{
		name = reader.ReadString();
		int num = reader.ReadInt32();
		wav = new List<string>();
		wavBank = new List<string>();
		for (int i = 0; i < num; i++)
		{
			wav.Add(reader.ReadString());
			wavBank.Add(reader.ReadString());
		}
		volume = reader.ReadSingle();
		pitch = reader.ReadSingle();
		category = reader.ReadInt32();
	}
}
