	public MgrSoundBank(SoundManager sndMgr)
	{
		this.sndMgr = sndMgr;
		title = "";
	}

	public void Read(BinaryReader reader)
	{
		title = reader.ReadString();
		int num = reader.ReadInt32();
		this.bankSound = new BankSound[num];
		for (int i = 0; i < num; i++)
		{
			BankSound bankSound = new BankSound();
			bankSound.Read(reader);
			this.bankSound[i] = bankSound;
		}
		num = reader.ReadInt32();
		this.bankCue = new BankCue[num];
		for (int j = 0; j < num; j++)
		{
			BankCue bankCue = new BankCue();
			bankCue.Read(reader);
			this.bankCue[j] = bankCue;
		}
	}

	internal void PlayCue(int cue)
	{
		bankCue[cue].Play(sndMgr, this);
	}

	internal int GetCueIdx(string cue)
	{
		for (int i = 0; i < bankCue.Length; i++)
		{
			if (bankCue[i].name == cue)
			{
				return i;
			}
		}
		return -1;
	}

	internal void PlayCue(string cue)
	{
		for (int i = 0; i < bankCue.Length; i++)
		{
			if (bankCue[i].name == cue)
			{
				bankCue[i].Play(sndMgr, this);
				break;
			}
		}
	}

	internal SoundEffectInstance GetCue(string cue)
	{
		for (int i = 0; i < bankCue.Length; i++)
		{
			if (bankCue[i].name == cue)
			{
				return bankCue[i].GetInstance(sndMgr, this);
			}
		}
		return null;
	}

	internal SoundEffectInstance GetCue(int idx)
	{
		return bankCue[idx].GetInstance(sndMgr, this);
	}

