	{
		return bankCue[idx].GetVol(sndMgr, this);
	}

	internal float GetPitch(int idx)
	{
		return bankCue[idx].GetPitch(sndMgr, this);
	}

	internal float GetVol(string cue)
	{
		for (int i = 0; i < bankCue.Length; i++)
		{
			if (bankCue[i].name == cue)
			{
				return bankCue[i].GetVol(sndMgr, this);
