public class SoundManager
{
	public MgrSoundBank[] soundBank;

	public MgrWaveBank[] waveBank;

	public void Read(BinaryReader reader, ContentManager Content)
	{
		int num = reader.ReadInt32();
		soundBank = new MgrSoundBank[num];
		for (int i = 0; i < num; i++)
		{
			MgrSoundBank mgrSoundBank = new MgrSoundBank(this);
			mgrSoundBank.Read(reader);
			soundBank[i] = mgrSoundBank;
		}
		num = reader.ReadInt32();
		waveBank = new MgrWaveBank[num];
		for (int j = 0; j < num; j++)
		{
			MgrWaveBank mgrWaveBank = new MgrWaveBank();
			mgrWaveBank.Read(reader, Content);
			waveBank[j] = mgrWaveBank;
		}
	}

	internal void PlaySnd(string bank, string cue)
	{
		for (int i = 0; i < soundBank.Length; i++)
		{
			if (!(soundBank[i].title == bank))
			{
				continue;
			}
			for (int j = 0; j < soundBank[i].bankCue.Length; j++)
			{
				if (soundBank[i].bankCue[j].name == cue)
				{
					soundBank[i].bankCue[j].Play(this, soundBank[i]);
				}
			}
		}
	}

	public MgrSoundBank GetSoundBank(string name)
	{
		for (int i = 0; i < soundBank.Length; i++)
		{
			if (soundBank[i].title == name)
			{
				return soundBank[i];
			}
		}
		return null;
	}

